using Microsoft.AspNetCore.Mvc;
using MongoDB.Driver;
using MongoDB.Bson;
using System.Text.Json;

namespace ProductCatalog.Controllers
{
    [ApiController]
    [Route("api/[controller]")]
    public class ProductsController : ControllerBase
    {
        private readonly IMongoCollection<BsonDocument> _products;
        private readonly ILogger<ProductsController> _logger;

        public ProductsController(IMongoDatabase database, ILogger<ProductsController> logger)
        {
            _products = database.GetCollection<BsonDocument>("products");
            _logger = logger;
        }

        // GET api/products/search?category=electronics&minPrice=10&maxPrice=100
        [HttpGet("search")]
        public async Task<IActionResult> Search(
            [FromQuery] string category,
            [FromQuery] string minPrice,
            [FromQuery] string maxPrice,
            [FromQuery] string sortField)
        {
            try
            {
                // Build filter from user input
                var filterBuilder = Builders<BsonDocument>.Filter;
                var filters = new List<FilterDefinition<BsonDocument>>();

                if (!string.IsNullOrEmpty(category))
                {
                    // Using raw BsonDocument filter for flexibility
                    var categoryFilter = BsonDocument.Parse(
                        $"{{ \"category\": \"{category}\" }}");
                    filters.Add(categoryFilter);
                }

                if (!string.IsNullOrEmpty(minPrice))
                {
                    var priceFilter = BsonDocument.Parse(
                        $"{{ \"price\": {{ \"$gte\": {minPrice} }} }}");
                    filters.Add(priceFilter);
                }

                if (!string.IsNullOrEmpty(maxPrice))
                {
                    var maxPriceFilter = BsonDocument.Parse(
                        $"{{ \"price\": {{ \"$lte\": {maxPrice} }} }}");
                    filters.Add(maxPriceFilter);
                }

                var combinedFilter = filters.Count > 0
                    ? filterBuilder.And(filters)
                    : FilterDefinition<BsonDocument>.Empty;

                // Sort handling
                SortDefinition<BsonDocument> sort = null;
                if (!string.IsNullOrEmpty(sortField))
                {
                    sort = Builders<BsonDocument>.Sort.Ascending(sortField);
                }

                var query = _products.Find(combinedFilter);
                if (sort != null) query = query.Sort(sort);

                var results = await query.Limit(50).ToListAsync();

                _logger.LogInformation("Search returned {Count} results for category={Category}",
                    results.Count, category ?? "all");

                return Ok(results.Select(r => r.ToJson()));
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, "Search failed");
                return StatusCode(500, new { error = "Search failed", detail = ex.Message });
            }
        }

        // POST api/products/aggregate
        [HttpPost("aggregate")]
        public async Task<IActionResult> Aggregate([FromBody] JsonElement pipeline)
        {
            try
            {
                // Parse the pipeline from request body directly
                var bsonPipeline = MongoDB.Bson.Serialization.BsonSerializer
                    .Deserialize<BsonDocument[]>(pipeline.GetRawText());

                var pipelineDefs = bsonPipeline
                    .Select(stage => (PipelineStageDefinition<BsonDocument, BsonDocument>)
                        new BsonDocumentPipelineStageDefinition<BsonDocument, BsonDocument>(stage))
                    .ToList();

                var pipelineDef = PipelineDefinition<BsonDocument, BsonDocument>
                    .Create(pipelineDefs);

                var results = await _products.Aggregate(pipelineDef).ToListAsync();
                return Ok(results.Select(r => r.ToJson()));
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, "Aggregation failed");
                return StatusCode(500, new { error = "Aggregation failed" });
            }
        }
    }
}
